using System.Security.Cryptography;
using System.Text;

var key = Encoding.UTF8.GetBytes("demo-secret-key-of-at-least-32-bytes");

string header = B64Url(Encoding.UTF8.GetBytes("""{"alg":"HS256","typ":"JWT"}"""));
string payload = B64Url(Encoding.UTF8.GetBytes("""{"sub":"42","role":"user"}"""));
string token = $"{header}.{payload}.{Sign(header, payload)}";

var parts = token.Split('.');
Console.WriteLine(parts.Length);
Console.WriteLine(parts[0]);
Console.WriteLine(Encoding.UTF8.GetString(FromB64Url(parts[1])));

string forged = B64Url(Encoding.UTF8.GetBytes("""{"sub":"42","role":"admin"}"""));
Console.WriteLine(Sign(parts[0], forged) == parts[2]);
Console.WriteLine(Sign(parts[0], parts[1]) == parts[2]);

string Sign(string h, string p) =>
    B64Url(HMACSHA256.HashData(key, Encoding.UTF8.GetBytes(h + "." + p)));

static string B64Url(byte[] b) =>
    Convert.ToBase64String(b).TrimEnd('=').Replace('+', '-').Replace('/', '_');

static byte[] FromB64Url(string s)
{
    s = s.Replace('-', '+').Replace('_', '/');
    return Convert.FromBase64String(s + new string('=', (4 - s.Length % 4) % 4));
}

byte[] data = { 0xFB, 0xFF, 0xBF, 0x41 };

string b64 = Convert.ToBase64String(data);
string url = b64.TrimEnd('=').Replace('+', '-').Replace('/', '_');
