string restored = url.Replace('-', '+').Replace('_', '/');
restored += new string('=', (4 - restored.Length % 4) % 4);
Console.WriteLine(Convert.FromBase64String(restored).Length);

using System.Text.Json;

using var doc = JsonDocument.Parse("""{"sub":"42","exp":1760000000}""");
long expValue = doc.RootElement.GetProperty("exp").GetInt64();

var exp = DateTimeOffset.FromUnixTimeSeconds(expValue);
Console.WriteLine(exp.ToString("u"));
Console.WriteLine(DateTimeOffset.FromUnixTimeMilliseconds(expValue).ToString("u"));

var skew = TimeSpan.FromMinutes(5);
foreach (int secondsAfterExp in new[] { 120, 300, 301 })
{
    var now = exp.AddSeconds(secondsAfterExp);
    Console.WriteLine($"{secondsAfterExp}: {(now <= exp + skew ? "accepted" : "expired")}");
}

